+// ── cache 辅助 ─────────────────────────────────────────────────
+
+func cacheStat(dir string) {
+	fmt.Println("新闻缓存目录:", dir)
+	fmt.Println()
+
+	subdirs := []struct {
+		name string
+		desc string
+	}{
+		{"feed_cache", "Feed 响应缓存（TTL 按来源 6-30min）"},
+		{"articles", "文章正文缓存（TTL 24h）"},
+		{"llm", "LLM 翻译/摘要缓存（TTL 7 天）"},
+		{"seen.json", "已读记录（7 天自动清理）"},
+	}
+
+	var totalSize int64
+	for _, s := range subdirs {
+		target := dir + "/" + s.name
+		sz := dirSize(target)
+		totalSize += sz
+		if sz == 0 && s.name != "seen.json" {
+			fmt.Printf("  %-15s （空）\n", s.name)
+		} else if sz > 0 {
+			files := countFiles(target)
+			fmt.Printf("  %-15s %s  %d 文件  —  %s\n", s.name, formatBytes(sz), files, s.desc)
+		}
+	}
+	fmt.Printf("\n总计: %s\n", formatBytes(totalSize))
+}
+
+// dirSize 递归计算目录/文件大小（不存在返回 0）。
+func dirSize(path string) int64 {
+	var total int64
+	fi, err := os.Stat(path)
+	if err != nil {
+		return 0
+	}
+	if !fi.IsDir() {
+		return fi.Size()
+	}
+	entries, err := os.ReadDir(path)
+	if err != nil {
+		return 0
+	}
+	for _, e := range entries {
+		info, err := e.Info()
+		if err != nil {
+			continue
+		}
+		if e.IsDir() {
+			total += dirSize(path + "/" + e.Name())
+		} else {
+			total += info.Size()
+		}
+	}
+	return total
+}
+
+func countFiles(path string) int {
+	fi, err := os.Stat(path)
+	if err != nil {
+		return 0
+	}
+	if !fi.IsDir() {
+		return 1
+	}
+	entries, _ := os.ReadDir(path)
+	return len(entries)
+}
+
+func formatBytes(n int64) string {
+	const unit = 1024
+	if n < unit {
+		return fmt.Sprintf("%d B", n)
+	}
+	div, exp := int64(unit), 0
+	for n2 := n / unit; n2 >= unit; n2 /= unit {
+		div *= unit
+		exp++
+	}
+	suffixes := []string{"KB", "MB", "GB"}
+	return fmt.Sprintf("%.1f %s", float64(n)/float64(div), suffixes[exp])
+}

