+func TestCleanPreservesParagraphs(t *testing.T) {
+	// clean 应压缩空白但保留 \n\n 段落分隔
+	input := "paragraph one.  \n\nparagraph two.\n\n\nparagraph three."
+	got := clean(input)
+	// 应保留段落分隔（\n\n 不变）
+	if !strings.Contains(got, "\n\n") {
