+// llmTranslateCmd 异步翻译正文。
+func llmTranslateCmd(client *llm.Client, body, lang string) tea.Cmd {
+	return func() tea.Msg {
+		// 先查缓存
+		if client.Cache() != nil {
+			key := llm.CacheKey(lang, lang, llm.InstTranslate)
+			// 翻译的缓存 key 用正文内容而非 URL（不同文章可能有相同片段）
