+// llmTranslateCmdCached 异步翻译，带缓存支持。
+func llmTranslateCmdCached(client *llm.Client, body, lang, cacheURL string) tea.Cmd {
+	return func() tea.Msg {
+		// 查缓存
+		if client.Cache() != nil {
+			key := llm.CacheKey(cacheURL, lang, llm.InstTranslate)
+			if cached, ok := client.Cache().Get(key); ok {
