+	if content == "" {
+		return
+	}
+	switch key {
+	case "## 背景":
+		r.Background = content
+	case "## 各方立场":
+		r.Positions = content
+	case "## 影响":
+		r.Impact = content
+	case "## 后续关注":
+		r.Outlook = content
+	}
+}
