// Set 写入缓存（含 ETag/Last-Modified 供条件请求）。
func (c *Cache) Set(url string, body []byte, etag, lastMod string) error {
	c.mu.Lock()
	defer c.mu.Unlock()
	e := Entry{
		URL:     url,
		Body:    body,
		Fetched: time.Now().UnixMilli(),
		ETag:    etag,
		LastMod: lastMod,
	}
	data, err := json.Marshal(e)
	if err != nil {
		return err
	}
	tmp := c.path(url) + ".tmp"
	if err := os.WriteFile(tmp, data, 0o644); err != nil {
		return err
	}
	return os.Rename(tmp, c.path(url))
}

// Purge 淘汰最旧文件至总大小 ≤ maxMB；返回删除文件数。
func (c *Cache) Purge() (int, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	entries, err := os.ReadDir(c.dir)
	if err != nil {
		return 0, err
	}
	type fi struct {
		name string
		size int64
		ts   int64
	}
	var files []fi
	var total int64
	for _, e := range entries {
		if e.IsDir() || filepath.Ext(e.Name()) == ".tmp" {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		total += info.Size()
		files = append(files, fi{name: e.Name(), size: info.Size(), ts: info.ModTime().Unix()})
	}
	if total <= c.maxMB || c.maxMB <= 0 {
		return 0, nil
	}
